// Model picker: thumbnails select the model shown in the rail (the carousel behaviour supplies the arrows and scrolling).
// Without script the thumbnails are plain links that jump to each model.
document.querySelectorAll('[data-bz-section="model-showcase"]').forEach(function (root) {
  var track = root.querySelector('[data-bz-part~="track"]');
  if (!track) return;
  var slides = [].slice.call(track.querySelectorAll('[data-bz-part~="slide"]'));
  var tiles = [].slice.call(root.querySelectorAll('.bz-col[data-bz-node^="ms-tile-"]'));
  if (!slides.length || tiles.length !== slides.length) return;
  function current() { var w = slides[0].offsetWidth || track.clientWidth; return Math.max(0, Math.min(slides.length - 1, Math.round(track.scrollLeft / w))); }
  function mark() {
    var i = current();
    tiles.forEach(function (tile, n) {
      if (n === i) { tile.setAttribute('data-active', ''); tile.querySelector('a').setAttribute('aria-current', 'true'); }
      else { tile.removeAttribute('data-active'); tile.querySelector('a').removeAttribute('aria-current'); }
    });
  }
  tiles.forEach(function (tile, n) {
    tile.querySelector('a').addEventListener('click', function (event) {
      event.preventDefault();
      var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      track.scrollTo({ left: slides[n].offsetLeft - track.offsetLeft, behavior: reduced ? 'auto' : 'smooth' });
    });
  });
  track.addEventListener('scroll', function () { window.requestAnimationFrame(mark); }, { passive: true });
  window.addEventListener('resize', mark, { passive: true });
  mark();
});
